/** Auto-generated compact Beta colorizer tables (RGB888 256x256). */
function decodeRgbTable(b64: string): Uint32Array {
  const bin = atob(b64);
  const out = new Uint32Array(65536);
  for (let i = 0, p = 0; i < 65536; i++, p += 3) {
    out[i] = (bin.charCodeAt(p) << 16) | (bin.charCodeAt(p + 1) << 8) | bin.charCodeAt(p + 2);
  }
  return out;
}

const GRASS_B64 = "";
const FOLIAGE_B64 = "";

export const GRASS_COLORIZER_TABLE: Uint32Array = decodeRgbTable(GRASS_B64);
export const FOLIAGE_COLORIZER_TABLE: Uint32Array = decodeRgbTable(FOLIAGE_B64);
